#!/usr/bin/env python3
# Some portions generated by Codex. Independent-fork analysis and warmup diagnostic.
import pathlib,sys,statistics,json
root=pathlib.Path(sys.argv[1]); out={}
for regime in ('regular','interpreted','janino','coscan'):
    fs=[]
    for file in sorted(root.glob(regime+'-*-*.log')):
        rows=[]
        for line in file.read_text().splitlines():
            if line.startswith(('audit ','coscan ')):
                r=dict(t.split('=',1) for t in line.split()[1:])
                if int(r['run'])>=0:rows.append(r)
        if len(rows)!=10:raise ValueError((file,len(rows)))
        vals=[int(r['totalNs'])/1e6 for r in rows]
        fs.append(dict(file=file.name,variant=file.stem.split('-')[-1],meanMs=statistics.mean(vals),minMs=min(vals),maxMs=max(vals),
                       firstHalfMs=statistics.mean(vals[:5]),secondHalfMs=statistics.mean(vals[5:]),byIndexMs=vals,
                       firstRowMs=None if regime=='coscan' else statistics.mean(int(r['firstRowNs'])/1e6 for r in rows)))
    if len(fs)!=8:raise ValueError((regime,len(fs)))
    pairs=[]
    for i in range(0,8,2):
        a,b=sorted(fs[i:i+2],key=lambda x:x['variant'])
        pairs.append(dict(A=a['file'],B=b['file'],deltaMs=b['meanMs']-a['meanMs'],latencyReductionPercent=100*(1-b['meanMs']/a['meanMs'])))
    out[regime]=dict(forks=fs,pairs=pairs,measuredIndexMeans=[statistics.mean(f['byIndexMs'][i] for f in fs) for i in range(10)])
print(json.dumps(out,indent=2))
